#!/usr/bin/env python3
"""Select the private executor for the invoking CI checkout when reachable."""

from __future__ import annotations

import os
import socket
from pathlib import Path


def configure_fleet(
    workspace: Path,
    output: Path,
    connection_outcome: str,
    runner_os: str,
    runner_arch: str,
    host: str = "ubuntu-main",
    port: int = 50051,
) -> bool:
    profile = {("Linux", "X64"): "rbe-linux", ("macOS", "ARM64"): "rbe-macos"}.get(
        (runner_os, runner_arch)
    )
    enabled = False
    if connection_outcome == "success" and profile:
        try:
            # This checks the coordinator, not the number or capacity of workers.
            with socket.create_connection((host, port), timeout=5):
                pass
            enabled = True
        except OSError as error:
            print(
                f"::warning::Private Bazel executor is unreachable: {error}; "
                "using hosted execution."
            )
    elif connection_outcome == "failure":
        print("::warning::Private Bazel enrollment failed; using hosted execution.")
    elif connection_outcome == "success":
        print(
            f"::warning::No fleet profile for {runner_os}/{runner_arch}; "
            "using hosted execution."
        )

    if enabled:
        rc = f"""# Generated by CI setup; workstation configuration is unchanged.
build --config={profile}
build --remote_executor=grpc://{host}:{port}
build --remote_cache=grpc://{host}:{port}
build --remote_instance_name=main
build --remote_timeout=600
# Retry infrastructure failures locally; compiler and test failures still fail.
build --remote_local_fallback
build --remote_local_fallback_strategy=sandboxed
build --remote_download_outputs=toplevel
build --jobs=40
build --local_resources=cpu=HOST_CPUS
build --local_resources=memory=HOST_RAM*.5
build --internal_spawn_scheduler
build --dynamic_local_strategy=sandboxed
build --dynamic_remote_strategy=remote
# asupersync and other Rust crates use the fleet first. Do not race large
# compilations on the hosted VM; local_resources does not cap rustc memory.
build --strategy=Rustc=remote
# Tag `local` requires the local strategy; dynamic-only cannot spawn those tests.
build --strategy=TestRunner=dynamic,local
build --bes_backend=grpc://ubuntu-main:1985
build --bes_results_url=https://ubuntu-main.tail039078.ts.net/invocation/
build --bes_timeout=30s
build --bes_upload_mode=fully_async
"""
    else:
        rc = "# Private executor unavailable or not configured; use hosted execution.\n"

    # This action owns the CI checkout's local rc. Clear a previous fleet
    # selection on retry, before advertising that hosted execution is selected.
    (workspace / ".bazelrc.local").write_text(rc)
    with output.open("a") as handle:
        handle.write(f"enabled={str(enabled).lower()}\n")
    return enabled


if __name__ == "__main__":
    configure_fleet(
        Path.cwd(),
        Path(os.environ["GITHUB_OUTPUT"]),
        os.environ.get("TAILSCALE_OUTCOME", ""),
        os.environ["RUNNER_OS"],
        os.environ["RUNNER_ARCH"],
    )
